create extension if not exists pgcrypto;
create type public.app_role as enum ('owner','manager','member');
create type public.booking_status as enum ('inquiry','negotiation','confirmed','completed','cancelled');
create type public.fee_split_status as enum ('draft','final');
create type public.payment_kind as enum ('deposit','installment','settlement','refund');
create type public.cash_direction as enum ('income','expense');

create table public.roles(id uuid primary key default gen_random_uuid(), key public.app_role not null unique, name text not null unique);
create table public.permissions(id uuid primary key default gen_random_uuid(), key text not null unique, name text not null);
create table public.role_permissions(role_id uuid references public.roles on delete cascade, permission_id uuid references public.permissions on delete cascade, primary key(role_id,permission_id));
create table public.profiles(id uuid primary key references auth.users on delete restrict, full_name text not null check(length(trim(full_name))>=2), email text not null unique, phone text, is_active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.user_roles(user_id uuid primary key references public.profiles on delete cascade, role_id uuid not null references public.roles on delete restrict, assigned_by uuid references public.profiles, assigned_at timestamptz not null default now());
create table public.positions(id uuid primary key default gen_random_uuid(), name text not null unique, is_active boolean not null default true, created_at timestamptz not null default now());
create table public.member_positions(member_id uuid references public.profiles on delete cascade, position_id uuid references public.positions on delete restrict, primary key(member_id,position_id));
create table public.external_hunters(id uuid primary key default gen_random_uuid(), name text not null, phone text, notes text, is_active boolean not null default true, created_at timestamptz not null default now(), created_by uuid references public.profiles);
create table public.event_types(id uuid primary key default gen_random_uuid(), name text not null unique, is_active boolean not null default true, created_at timestamptz not null default now());
create table public.venues(id uuid primary key default gen_random_uuid(), name text not null, location text, maps_url text, created_at timestamptz not null default now(), unique(name,location));
create table public.events(id uuid primary key default gen_random_uuid(), name text not null, venue_id uuid references public.venues, location text not null, event_type_id uuid not null references public.event_types, starts_at timestamptz not null, duration_minutes integer not null check(duration_minutes between 15 and 1440), contract_value bigint not null check(contract_value>=0), booking_status public.booking_status not null default 'inquiry', maps_url text, client_pic text, client_contact text, notes text, created_by uuid not null references public.profiles, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.event_assignments(id uuid primary key default gen_random_uuid(), event_id uuid not null references public.events on delete cascade, member_id uuid not null references public.profiles on delete restrict, position_id uuid not null references public.positions, created_at timestamptz not null default now(), unique(event_id,member_id,position_id));
create table public.event_hunters(id uuid primary key default gen_random_uuid(), event_id uuid not null references public.events on delete cascade, member_id uuid references public.profiles, external_hunter_id uuid references public.external_hunters, created_at timestamptz not null default now(), check(num_nonnulls(member_id,external_hunter_id)=1), unique(event_id,member_id), unique(event_id,external_hunter_id));
create table public.event_status_history(id uuid primary key default gen_random_uuid(), event_id uuid not null references public.events on delete cascade, old_status public.booking_status, new_status public.booking_status not null, reason text, changed_by uuid not null references public.profiles, created_at timestamptz not null default now());

create table public.fee_templates(id uuid primary key default gen_random_uuid(), name text not null unique, is_active boolean not null default true, created_by uuid references public.profiles, created_at timestamptz not null default now());
create table public.fee_template_items(id uuid primary key default gen_random_uuid(), template_id uuid not null references public.fee_templates on delete cascade, component_key text not null, calculation_type text not null check(calculation_type in('percentage','fixed','remainder')), value bigint not null check(value>=0), sort_order integer not null default 0, unique(template_id,component_key));
create table public.fee_splits(id uuid primary key default gen_random_uuid(), event_id uuid not null references public.events on delete restrict, version integer not null default 1 check(version>0), status public.fee_split_status not null default 'draft', contract_snapshot bigint not null check(contract_snapshot>=0), revision_reason text, finalized_at timestamptz, finalized_by uuid references public.profiles, created_by uuid not null references public.profiles, created_at timestamptz not null default now(), unique(event_id,version));
create table public.fee_allocations(id uuid primary key default gen_random_uuid(), fee_split_id uuid not null references public.fee_splits on delete restrict, component_key text not null, recipient_member_id uuid references public.profiles, recipient_hunter_id uuid references public.external_hunters, is_cash_allocation boolean not null default false, amount bigint not null check(amount>=0), percentage_bps integer check(percentage_bps between 0 and 10000), created_at timestamptz not null default now(), check(num_nonnulls(recipient_member_id,recipient_hunter_id)+(is_cash_allocation::integer)=1));
create table public.allocation_revisions(id uuid primary key default gen_random_uuid(), fee_split_id uuid not null references public.fee_splits, reason text not null, snapshot jsonb not null, created_by uuid not null references public.profiles, created_at timestamptz not null default now());

create table public.client_payments(id uuid primary key default gen_random_uuid(), event_id uuid not null references public.events, kind public.payment_kind not null, amount bigint not null check(amount>0), paid_at timestamptz not null, method text not null, notes text, proof_document_id uuid, reversal_of uuid references public.client_payments, idempotency_key uuid not null unique default gen_random_uuid(), created_by uuid not null references public.profiles, created_at timestamptz not null default now());
create table public.payouts(id uuid primary key default gen_random_uuid(), recipient_member_id uuid references public.profiles, recipient_hunter_id uuid references public.external_hunters, amount bigint not null check(amount>0), paid_at timestamptz not null, method text not null, notes text, proof_document_id uuid, reversal_of uuid references public.payouts, idempotency_key uuid not null unique default gen_random_uuid(), created_by uuid not null references public.profiles, created_at timestamptz not null default now(), check(num_nonnulls(recipient_member_id,recipient_hunter_id)=1));
create table public.payout_allocations(payout_id uuid references public.payouts on delete restrict, fee_allocation_id uuid references public.fee_allocations on delete restrict, amount bigint not null check(amount>0), primary key(payout_id,fee_allocation_id));
create table public.cash_accounts(id uuid primary key default gen_random_uuid(), name text not null unique, is_active boolean not null default true, created_at timestamptz not null default now());
create table public.cash_categories(id uuid primary key default gen_random_uuid(), name text not null unique, direction public.cash_direction not null, is_active boolean not null default true);
create table public.cash_transactions(id uuid primary key default gen_random_uuid(), cash_account_id uuid not null references public.cash_accounts, category_id uuid not null references public.cash_categories, direction public.cash_direction not null, amount bigint not null check(amount>0), transacted_at timestamptz not null, description text not null, source_client_payment_id uuid references public.client_payments, reversal_of uuid references public.cash_transactions, proof_document_id uuid, idempotency_key uuid not null unique default gen_random_uuid(), created_by uuid not null references public.profiles, created_at timestamptz not null default now());

create table public.documents(id uuid primary key default gen_random_uuid(), name text not null, category text not null, storage_path text not null unique, mime_type text not null, size_bytes bigint not null check(size_bytes between 1 and 20971520), event_id uuid references public.events, owner_member_id uuid references public.profiles, is_financial boolean not null default false, expires_at date, archived_at timestamptz, uploaded_by uuid not null references public.profiles, created_at timestamptz not null default now());
alter table public.client_payments add constraint client_payment_proof_fk foreign key(proof_document_id) references public.documents;
alter table public.payouts add constraint payout_proof_fk foreign key(proof_document_id) references public.documents;
alter table public.cash_transactions add constraint cash_proof_fk foreign key(proof_document_id) references public.documents;
create table public.document_versions(id uuid primary key default gen_random_uuid(), document_id uuid not null references public.documents on delete cascade, storage_path text not null unique, version integer not null check(version>0), size_bytes bigint not null, uploaded_by uuid not null references public.profiles, created_at timestamptz not null default now(), unique(document_id,version));
create table public.notifications(id uuid primary key default gen_random_uuid(), recipient_id uuid not null references public.profiles on delete cascade, title text not null, body text not null, kind text not null, entity_type text, entity_id uuid, read_at timestamptz, created_at timestamptz not null default now());
create table public.audit_logs(id bigint generated always as identity primary key, actor_id uuid references public.profiles, action text not null, entity_type text not null, entity_id uuid, old_data jsonb, new_data jsonb, created_at timestamptz not null default now());
create table public.app_settings(key text primary key, value jsonb not null, updated_by uuid references public.profiles, updated_at timestamptz not null default now());

create index events_starts_at_idx on public.events(starts_at);
create index events_status_idx on public.events(booking_status);
create index assignments_member_idx on public.event_assignments(member_id,event_id);
create index allocations_member_idx on public.fee_allocations(recipient_member_id);
create index notifications_recipient_idx on public.notifications(recipient_id,read_at,created_at desc);
create index documents_event_idx on public.documents(event_id);
